import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css"; // reuse card/grid styling
import "./Questionnaire.css";  // reuse form styles if needed

function SpendingPriority() {
  const navigate = useNavigate();

  const categories = [
    "Food & Groceries",
    "Shopping",
    "Bills",
    "Health",
    "Entertainment",
    "Transport"
  ];

  const [selected, setSelected] = useState({});
  const [values, setValues] = useState({});

  const toggleCategory = (cat) => {
    setSelected((prev) => ({
      ...prev,
      [cat]: !prev[cat]
    }));

    // initialize slider if first time opened
    setValues((prev) => ({
      ...prev,
      [cat]: prev[cat] ?? 3
    }));
  };

  const handleSlider = (cat, val) => {
    setValues((prev) => ({
      ...prev,
      [cat]: Number(val)
    }));
  };

  const handleContinue = () => {
    const filtered = Object.keys(values).filter(
      (cat) => selected[cat] && values[cat] >= 3
    );

    navigate("/budget", { state: { categories: filtered } });
  };

  return (
    <div className="income-container">
      <h1 className="income-title">Set Your Spending Priorities</h1>
      <p className="income-subtitle">
        Select categories and assign priority (0–5)
      </p>

      <div className="income-grid">
        {categories.map((cat) => (
          <div
            key={cat}
            className="income-card"
            onClick={() => toggleCategory(cat)}
            style={{
              border: selected[cat]
                ? "2px solid #1e3c72"
                : "1px solid #dcdcdc"
            }}
          >
            <div className="income-name">{cat}</div>

            {selected[cat] && (
              <div style={{ marginTop: "15px" }}>
                <input
                  type="range"
                  min="0"
                  max="5"
                  value={values[cat]}
                  onChange={(e) => handleSlider(cat, e.target.value)}
                  style={{ width: "100%" }}
                />
                <div style={{ textAlign: "center", marginTop: "5px" }}>
                  Priority: {values[cat]}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      <button
        className="next-button"
        style={{ maxWidth: "300px" }}
        onClick={handleContinue}
      >
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
